function loadEasyNumberSeparator(componentId) {
    var result = $('#' + componentId + "_result").val();
    if (result != null && result != undefined && result != "") {
        $('#' + componentId).val(result);
    }

    easyNumberSeparator({
        selector: '#' + componentId,
        separator: '.',
        decimalSeparator: ',',
        resultInput: '#' + componentId + "_result",
    });
}